#[test]
fn d102_pins_eval_w() {
    for row in PINS {
        let (id, ew0, ew1) = (row.0, row.1, row.2);
        // Per-record W: identity for record 0, the fixed non-trivial W for
        // record 1 (MFEM SetTargetJacobian per quadrature record).
        let w0 = sample_w(id, 0);
        let w1 = sample_w(id, 1);
        if id < 300 {
            let m = metric_2d(id);
            let j0 = sample_jpt(id, 0);
            let j1 = sample_jpt(id, 1);
            m.set_target_jacobian(&[[w0[0], w0[2]], [w0[1], w0[3]]]);
            let v0 = m.eval_w(&[[j0[0], j0[2]], [j0[1], j0[3]]]);
            m.set_target_jacobian(&[[w1[0], w1[2]], [w1[1], w1[3]]]);
            let v1 = m.eval_w(&[[j1[0], j1[2]], [j1[1], j1[3]]]);
            assert!(close(v0, ew0), "id {id}: EvalW(rec0) {v0} vs pin {ew0}");
            assert!(close(v1, ew1), "id {id}: EvalW(rec1) {v1} vs pin {ew1}");
        } else {
            // No 3D A-metrics exist in MFEM, so the 3D trait carries no
            // set_target_jacobian hook; the W samples are irrelevant here.
            let m = metric_3d(id);
            let pick =
                |v: &Vec<f64>| [[v[0], v[3], v[6]], [v[1], v[4], v[7]], [v[2], v[5], v[8]]];
            let v0 = m.eval_w(&pick(&sample_jpt(id, 0)));
            let v1 = m.eval_w(&pick(&sample_jpt(id, 1)));
            assert!(close(v0, ew0), "id {id}: EvalW(rec0) {v0} vs pin {ew0}");
            assert!(close(v1, ew1), "id {id}: EvalW(rec1) {v1} vs pin {ew1}");
        }
    }
}

#[test]
fn d102_pins_eval_p_and_h() {
    for row in PINS {
        let (id, ep0, eh0) = (row.0, row.4, row.5);
        if ep0.is_empty() {
            // 211/313: no C++ reference path — covered by the FD test below.
            continue;
        }
        let j0 = sample_jpt(id, 0);
        let (ds, weight) = sample_ds_weight(id, 0);
        if id < 300 {
            let m = metric_2d(id);
            let jpt = [[j0[0], j0[2]], [j0[1], j0[3]]];
            let mut p = [[0.0f64; 2]; 2];
            m.eval_p(&jpt, &mut p);
            assert!(close(p[0][0], ep0), "id {id}: EvalP[0] {} vs pin {ep0}", p[0][0]);
            let ds_rows: Vec<[f64; 2]> = (0..4).map(|i| [ds[i], ds[i + 4]]).collect();
            let mut a = vec![0.0f64; 64];
            m.assemble_h(&jpt, &ds_rows, weight, &mut a);
            assert!(close(a[0], eh0), "id {id}: AssembleH[0] {} vs pin {eh0}", a[0]);
        } else {
            let m = metric_3d(id);
            let jpt = [[j0[0], j0[3], j0[6]], [j0[1], j0[4], j0[7]], [j0[2], j0[5], j0[8]]];
            let mut p = [[0.0f64; 3]; 3];
            m.eval_p(&jpt, &mut p);
            assert!(close(p[0][0], ep0), "id {id}: EvalP[0] {} vs pin {ep0}", p[0][0]);
            let ds_rows: Vec<[f64; 3]> =
                (0..8).map(|i| [ds[i], ds[i + 8], ds[i + 16]]).collect();
            let mut a = vec![0.0f64; 24 * 24];
            m.assemble_h(&jpt, &ds_rows, weight, &mut a);
            assert!(close(a[0], eh0), "id {id}: AssembleH[0] {} vs pin {eh0}", a[0]);
        }
    }
}

/// Metrics 211 (2D) and 313 (3D): MFEM 4.10 implements only EvalW (EvalP and
/// AssembleH abort). fem-rs completes them analytically; verify their
/// derivatives against central finite differences of their own EvalW / EvalP.
#[test]
fn d102_no_cpp_deriv_metrics_are_fd_consistent() {
    let h = 1e-6;

    // 211 in 2D.
    {
        let m = metric_2d(211);
        let jpt = [[0.8, 0.3], [-0.2, 1.15]];
        let mut p = [[0.0f64; 2]; 2];
        m.eval_p(&jpt, &mut p);
        for r in 0..2 {
            for c in 0..2 {
                let mut jp = jpt;
                let mut jm = jpt;
                jp[r][c] += h;
                jm[r][c] -= h;
                let fd = (m.eval_w(&jp) - m.eval_w(&jm)) / (2.0 * h);
                assert!(
                    (p[r][c] - fd).abs() <= 1e-5 * (1.0 + fd.abs()),
                    "211 P[{r}][{c}] {} vs fd {fd}",
                    p[r][c]
                );
            }
        }
        // AssembleH vs the central-FD Hessian of P, contracted like
        // DefaultAssembleH.
        let ds = [[0.3, -0.2], [0.1, 0.4], [-0.35, 0.15], [0.22, 0.31]];
        let weight = 0.7;
        let mut a = vec![0.0f64; 64];
        m.assemble_h(&jpt, &ds, weight, &mut a);
        let mut dp = vec![[0.0f64; 4]; 4]; // dp[je][pe] = dP_pe/dJ_je (flat)
        for je in 0..4 {
            let (r, c) = (je % 2, je / 2);
            let mut jp = jpt;
            let mut jm = jpt;
            jp[r][c] += h;
            jm[r][c] -= h;
            let mut pp = [[0.0f64; 2]; 2];
            let mut pm = [[0.0f64; 2]; 2];
            m.eval_p(&jp, &mut pp);
            m.eval_p(&jm, &mut pm);
            for s in 0..4 {
                let (sr, sc) = (s % 2, s / 2);
                dp[je][s] = (pp[sr][sc] - pm[sr][sc]) / (2.0 * h);
            }
        }
        // Contraction reference (MFEM DefaultAssembleH convention):
        // A(i + pr*2, j + jr*2) += w * DS(i, pc) * DS(j, jc) * dP_prpc/dJ_jrjc.
        let mut a_ref = vec![0.0f64; 64];
        for pr in 0..2 {
            for pc in 0..2 {
                for jr in 0..2 {
                    for jc in 0..2 {
                        let je = jr + jc * 2;
                        let pe = pr + pc * 2;
                        for i in 0..4usize {
                            for j in 0..4usize {
                                a_ref[i + pr * 4 + (j + jr * 4) * 8] +=
                                    weight * ds[i][pc] * ds[j][jc] * dp[je][pe];
                            }
                        }
                    }
                }
            }
        }
        for k in 0..a.len() {
            assert!(
                (a[k] - a_ref[k]).abs() <= 1e-5 * (1.0 + a_ref[k].abs()),
                "211 A[{k}] {} vs fd {}",
                a[k],
                a_ref[k]
            );
        }
    }

    // 313 in 3D (same structure).
    {
        let m = metric_3d(313);
        let jpt = [[1.05, 0.22, -0.12], [0.31, 0.94, 0.4], [-0.06, 0.18, 1.2]];
        let mut p = [[0.0f64; 3]; 3];
        m.eval_p(&jpt, &mut p);
        for r in 0..3 {
            for c in 0..3 {
                let mut jp = jpt;
                let mut jm = jpt;
                jp[r][c] += h;
                jm[r][c] -= h;
                let fd = (m.eval_w(&jp) - m.eval_w(&jm)) / (2.0 * h);
                assert!(
                    (p[r][c] - fd).abs() <= 1e-5 * (1.0 + fd.abs()),
                    "313 P[{r}][{c}] {} vs fd {fd}",
                    p[r][c]
                );
            }
        }
        let nd = 8usize;
        let mut ds = vec![0.0f64; nd * 3];
        for i in 0..nd {
            for d in 0..3 {
                ds[i + d * nd] = frac(0.61 * i as f64 + 0.17 * d as f64 + 0.29) - 0.5;
            }
        }
        let ds_rows: Vec<[f64; 3]> =
            (0..nd).map(|i| [ds[i], ds[i + nd], ds[i + 2 * nd]]).collect();
        let weight = 0.9;
        let mut a = vec![0.0f64; nd * 3 * nd * 3];
        m.assemble_h(&jpt, &ds_rows, weight, &mut a);
        let mut dp = vec![[0.0f64; 9]; 9]; // dp[je][pe] = dP_pe/dJ_je (flat)
        for je in 0..9 {
            let (r, c) = (je % 3, je / 3);
            let mut jp = jpt;
            let mut jm = jpt;
            jp[r][c] += h;
            jm[r][c] -= h;
            let mut pp = [[0.0f64; 3]; 3];
            let mut pm = [[0.0f64; 3]; 3];
            m.eval_p(&jp, &mut pp);
            m.eval_p(&jm, &mut pm);
            for s in 0..9 {
                let (sr, sc) = (s % 3, s / 3);
                dp[je][s] = (pp[sr][sc] - pm[sr][sc]) / (2.0 * h);
            }
        }
        let mut a_ref = vec![0.0f64; nd * 3 * nd * 3];
        for pr in 0..3 {
            for pc in 0..3 {
                for jr in 0..3 {
                    for jc in 0..3 {
                        let je = jr + jc * 3;
                        let pe = pr + pc * 3;
                        for i in 0..nd {
                            for j in 0..nd {
                                a_ref[i + pr * nd + (j + jr * nd) * nd * 3] +=
                                    weight * ds_rows[i][pc] * ds_rows[j][jc] * dp[je][pe];
                            }
                        }
                    }
                }
            }
        }
        for k in 0..a.len() {
            assert!(
                (a[k] - a_ref[k]).abs() <= 1e-5 * (1.0 + a_ref[k].abs()),
                "313 A[{k}] {} vs fd {}",
                a[k],
                a_ref[k]
            );
        }
    }
}
